package remframework.geometry.discovery;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;
public final class GeometryConfigurationStore {
    private final Path root;
    public GeometryConfigurationStore(Path root){this.root=root;}
    public static GeometryConfigurationStore defaults(){return new GeometryConfigurationStore(Path.of("lattice/geometry-discovery/configuration-sets"));}
    public Path save(GeometryConfigurationGenerationResult result)throws IOException{Path set=root.resolve(result.setId()),details=set.resolve("configurations");Files.createDirectories(details);Files.writeString(set.resolve("request.toml"),request(result.request()),StandardCharsets.UTF_8);StringBuilder csv=new StringBuilder("configurationId,N,K,edgeCount,symmetry,automorphismCount,status,geometryTestStatus,diagnosticSummary\n");for(GeometryConfiguration c:result.configurations()){Files.writeString(details.resolve(c.id()+".toml"),configuration(c),StandardCharsets.UTF_8);csv.append(c.id()).append(',').append(c.nodeCount()).append(',').append(c.exactDegree()).append(',').append(c.edges().size()).append(',').append(c.graphSymmetry()).append(',').append(c.automorphismGroupSize()).append(',').append(c.status().code()).append(",NOT_TESTED,").append(csv(c.status().summary())).append('\n');}Files.writeString(set.resolve("configurations.csv"),csv,StandardCharsets.UTF_8);Files.writeString(set.resolve("generation-summary.toml"),summary(result),StandardCharsets.UTF_8);return set;}
    public List<GeometryConfiguration> reopen(Path set)throws IOException{List<GeometryConfiguration> result=new ArrayList<>();Path directory=set.resolve("configurations");if(Files.notExists(directory))return result;try(var files=Files.list(directory)){for(Path file:files.filter(p->p.toString().endsWith(".toml")).sorted().toList())result.add(parse(file));}return result;}
    private String request(GeometryConfigurationRequest r){return "node_count = "+r.nodeCount()+"\nexact_degree = "+r.exactDegree()+"\nintended_dimension = \""+r.intendedDimension()+"\"\nsymmetry_filter = \""+r.symmetryFilter()+"\"\nmaximum_configurations = "+r.maximumConfigurations()+"\nenumeration_time_millis = "+r.enumerationTimeLimit().toMillis()+"\ngeneration_strategy = \""+r.generationStrategy()+"\"\n";}
    private String configuration(GeometryConfiguration c){StringBuilder s=new StringBuilder();s.append("configuration_id = \"").append(c.id()).append("\"\nnode_count = ").append(c.nodeCount()).append("\nexact_degree = ").append(c.exactDegree()).append("\ncanonical_graph_label = \"").append(c.canonicalGraphLabel()).append("\"\nisomorphism_class_id = \"").append(c.isomorphismClassId()).append("\"\nautomorphism_group_size = ").append(c.automorphismGroupSize()).append("\ngraph_symmetry = \"").append(c.graphSymmetry()).append("\"\nconnected = true\ngeneration_index = ").append(c.generationIndex()).append("\ngeneration_method = \"").append(c.generationMethod()).append("\"\nenumeration_complete = ").append(c.enumerationComplete()).append("\nstatus = \"").append(c.status().code()).append("\"\ncreated_at = \"").append(c.creationTimestamp()).append("\"\nedges = [");for(int i=0;i<c.edges().size();i++){if(i>0)s.append(", ");DiscoveryConnection e=c.edges().get(i);s.append("[").append(e.firstNodeId()).append(", ").append(e.secondNodeId()).append("]");}return s.append("]\n").toString();}
    private String summary(GeometryConfigurationGenerationResult r){GeometryConfigurationMetrics m=r.metrics();return "set_id = \""+r.setId()+"\"\nconfigurations_examined = "+m.configurationsExamined()+"\nunique_retained = "+m.uniqueConfigurationsRetained()+"\nisomorphic_duplicates_removed = "+m.isomorphicDuplicatesRemoved()+"\nsymmetric_count = "+m.symmetricCount()+"\nasymmetric_count = "+m.asymmetricCount()+"\nelapsed_milliseconds = "+m.elapsedMilliseconds()+"\nenumeration_complete = "+m.enumerationComplete()+"\nstatus = \""+r.status().code()+"\"\n";}
    private GeometryConfiguration parse(Path file)throws IOException{Map<String,String> v=new HashMap<>();for(String line:Files.readAllLines(file)){int at=line.indexOf('=');if(at>0)v.put(line.substring(0,at).trim(),line.substring(at+1).trim());}int n=Integer.parseInt(v.get("node_count")),k=Integer.parseInt(v.get("exact_degree"));List<DiscoveryConnection> edges=new ArrayList<>();java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\[(\\d+),\\s*(\\d+)\\]").matcher(v.get("edges"));while(m.find())edges.add(new DiscoveryConnection(Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2))));var d=GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.COMPLETE,GeometryConfigurationStatusCode.valueOf(unquote(v.get("status"))),"Reopened configuration","Topology-only configuration reopened from persistent storage.");return new GeometryConfiguration(new GeometryConfigurationId(unquote(v.get("configuration_id"))),n,k,edges,null,unquote(v.get("canonical_graph_label")),unquote(v.get("isomorphism_class_id")),Long.parseLong(v.get("automorphism_group_size")),GraphSymmetryClassification.valueOf(unquote(v.get("graph_symmetry"))),true,Integer.parseInt(v.get("generation_index")),unquote(v.get("generation_method")),Boolean.parseBoolean(v.get("enumeration_complete")),GeometryConfigurationStatus.of(d),List.of(d),Instant.parse(unquote(v.get("created_at"))),Map.of());}
    private String unquote(String s){return s.startsWith("\"")?s.substring(1,s.length()-1):s;}
    private String csv(String s){return "\""+s.replace("\"","\"\"")+"\"";}
}
